    /// Reports what the published `node` datamodel variable holds now
    /// (W3C SCXML 5.2). Only the machine writes it.
    public var node: UInt64 { vNode }

    /// Reports what the published `clock` datamodel variable holds now
    /// (W3C SCXML 5.2). Only the machine writes it.
    public var clock: TodoPeerHlcRecord { vClock }

    /// Reports what the published `adds` datamodel variable holds now
    /// (W3C SCXML 5.2). Only the machine writes it.
    public var adds: [TodoPeerEntryRecord] { vAdds }

    /// Reports what the published `values` datamodel variable holds now
    /// (W3C SCXML 5.2). Only the machine writes it.
    public var values: [TodoPeerValueRecord] { vValues }

    /// Reports what the published `refusals` datamodel variable holds now
    /// (W3C SCXML 5.2). Only the machine writes it.
    public var refusals: UInt32 { vRefusals }

    /// Reports what the published `agenda` datamodel variable holds now
    /// (W3C SCXML 5.2). Only the machine writes it.
    public var agenda: [TodoPeerOccurrenceRecord] { vAgenda }

    /// Reports what the published `agendaNext` datamodel variable holds now
    /// (W3C SCXML 5.2). Only the machine writes it.
    public var agendaNext: UInt32 { vAgendaNext }

    /// Reports what the published `full` datamodel variable holds now
    /// (W3C SCXML 5.2). Only the machine writes it.
    public var full: UInt32 { vFull }

    /// Reports what the published `denied` datamodel variable holds now
    /// (W3C SCXML 5.2). Only the machine writes it.
    public var denied: UInt32 { vDenied }

    /// W3C SCXML 6.4.1: the values a parent's `<param>` and `namelist` give this
    /// machine's variables before it starts, each in the slot named as its
    /// variable's property is. A slot left `nil` keeps the value its `<data>` gave
    /// it; a variable that may be absent is handed the optional value whole.
    public struct InvokeParams {
        public init() {}
        public var vNode: UInt64? = nil
        public var vTyped: String? = nil
        public var vWasLive: Bool? = nil
        public var vPresent: Bool? = nil
        public var vRefusals: UInt32? = nil
        public var vAgendaNext: UInt32? = nil
        public var vZoneRows: UInt32? = nil
        public var vSplit: Bool? = nil
        public var vRawCount: UInt32? = nil
        public var vRawLast: UInt32? = nil
        public var vUtcSec: Int64? = nil
        public var vRoomValues: UInt32? = nil
        public var vFull: UInt32? = nil
        public var vGone: UInt32? = nil
        public var vDenied: UInt32? = nil
        public var vForbidden: Bool? = nil
        public var vAuthorized: Bool? = nil
        public var vTook: UInt32? = nil
    }

    /// Gives this machine the values `params` carries, in place of the ones its
    /// `<data>` gave. Called before the machine starts.
    public func acceptParams(_ params: InvokeParams) {
        if let value = params.vNode {
            vNode = value
        }
        if let value = params.vTyped {
            vTyped = value
        }
        if let value = params.vWasLive {
            vWasLive = value
        }
        if let value = params.vPresent {
            vPresent = value
        }
        if let value = params.vRefusals {
            vRefusals = value
        }
        if let value = params.vAgendaNext {
            vAgendaNext = value
        }
        if let value = params.vZoneRows {
            vZoneRows = value
        }
        if let value = params.vSplit {
            vSplit = value
        }
        if let value = params.vRawCount {
            vRawCount = value
        }
        if let value = params.vRawLast {
            vRawLast = value
        }
        if let value = params.vUtcSec {
            vUtcSec = value
        }
        if let value = params.vRoomValues {
            vRoomValues = value
        }
        if let value = params.vFull {
            vFull = value
        }
        if let value = params.vGone {
            vGone = value
        }
        if let value = params.vDenied {
            vDenied = value
        }
        if let value = params.vForbidden {
            vForbidden = value
        }
        if let value = params.vAuthorized {
            vAuthorized = value
        }
        if let value = params.vTook {
            vTook = value
        }
    }

    public init() {
        sessionID = drawSessionID()
    }

    /// Gives this session the id its host has for it, in place of the one it
    /// drew: an XML Nmtoken, since another session addresses this one as
    /// `#_scxml_<id>` and every child's id is this one's and the id the child was
    /// started under (docs/adr/0045). Refused for anything else.
    public func setSessionID(_ id: String) throws {
        let reason = sessionIDRefusalOf(id)
        if !reason.isEmpty {
            throw SendArgumentError(reason)
        }
        sessionID = id
    }

    // ------------------------------------------------------------------
    // Delivery to the parent (W3C SCXML 6.2 + 6.4)
    // ------------------------------------------------------------------

    /// Delivers a delayed `<send target="#_parent">` whose wait is over, with the
    /// payload an immediate one carries (W3C SCXML 6.2 + 6.4). It waited in this
    /// machine's own queue, so `<cancel>` reached it and a child that ended first
    /// dropped it: the engine dispatches nothing once final. Emitted for every
    /// machine, since the one that needs it is an invoked child, which need not
    /// invoke anything itself.
    public func deliverToParent(eventName: String, eventData: String) -> Bool {
        guard let parentEventQueue else {
            return false
        }
        parentEventQueue.push(ParentEvent(name: eventName, data: eventData))
        return true
    }

    /// Whether a session invoked this one (W3C SCXML C.1): the queue the invoking
    /// parent installs is the link to it.
    public var hasParentSession: Bool {
        parentEventQueue != nil
    }

    /// Whether `sessionID` names the session that invoked this one (W3C SCXML C.1). The
    /// location a session publishes is a target, so a reply sent to the origin of an
    /// event the parent sent, its location, reaches the parent as `#_parent` does
    /// (docs/adr/0090). The queue the parent installed knows who installed it.
    public func isParentSession(_ sessionID: String) -> Bool {
        guard let parentEventQueue, !sessionID.isEmpty else {
            return false
        }
        return parentEventQueue.parentSessionID.utf8.elementsEqual(sessionID.utf8)
    }

    // ======================================================================
    // StatePolicy implementation
    // ======================================================================

    /// The initial state (W3C SCXML 3.3).
    public func initialState() -> TodoPeerState {
        .open
    }

    /// Whether `state` is a `<final>` state (W3C SCXML 3.7).
    public func isFinalState(_ state: TodoPeerState) -> Bool {
        switch state {
        default:
            return false
        }
